class Solution {
public:
    vector<string> beforeAndAfterPuzzles(vector<string>& phrases) {
        set<string> result;
        for (int i = 0; i < static_cast<int>(phrases.size()); ++i) {
            for (int j = 0; j < static_cast<int>(phrases.size()); ++j) {
                if (i == j) {
                    continue;
                }
                int last = phrases[i].find_last_of(' ');
                int first = phrases[j].find(' ');
                string tail = phrases[i].substr(
                    last == string::npos ? 0 : last + 1);
                string head = phrases[j].substr(0, first);
                if (tail == head) {
                    result.insert(phrases[i] +
                        (first == string::npos ? "" : phrases[j].substr(first)));
                }
            }
        }
        return vector<string>(result.begin(), result.end());
    }
};
